                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît évident <E049><E003 8><E025 2>que toute nouvelle discussion sur cette affaire\r\nsera vaine.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Barok Van Peers, <E049><E003 8><E025 2>j'ose croire que, si égaré\r\nfût-il...");
