            // [119] BB\script\output\_sce04_c403_0060_eng#2
            entryTranslators[@"BB\script\output\_sce04_c403_0060_eng#2"] = (s) => {
                R(ref s, "‘I pen this, <E003 10>my last will and testament, <E003 12>in the final\r\n<E042><CNTR>moments before my inevitable and willing death.’", "« Je rédige ici, <E003 10>mon testament authentique, <E003 12>dans les ultimes\r\n<E042><CNTR>instants précédant ma mort inéluctable et consentie. »");
                R(ref s, "‘The hour is 11 p.m. <E003 10>and I sit at my writing desk in my\r\n<E042><CNTR>office; <E003 12>my good friend Asogi stands at my shoulder.’", "« Il est 23 heures <E003 10>et je suis assis à mon écritoire dans mon\r\n<E042><CNTR>cabinet d'étude ; <E003 12>mon cher ami Asogi se tient à mes côtés. »");
                R(ref s, "‘He has expressed his intent to invoke the dying ritual\r\n<E042><CNTR>of the duel, <E003 12>that I may depart this world with honour.’", "« Il a exprimé le dessein d'invoquer le rituel sacré\r\n<E042><CNTR>du duel, <E003 12>afin que je quitte ce monde avec honneur. »");
                R(ref s, "‘An honour of which I am utterly undeserving.<E003 15>\r\n<E042><CNTR>The Japanese are a truly merciful people.’", "« Un honneur dont je suis pourtant indigne.<E003 15>\r\n<E042><CNTR>Les Japonais sont un peuple d'une noblesse et d'une clémence infinies. »");
                R(ref s, "‘I, <E003 8>Klint van Zieks, <E003 10>lord of the manor of the van Zieks\r\n<E042><CNTR>estate,<E003 12> hereby confess to the following:’", "« Moi, <E003 8>Klint Van Peers, <E003 10>seigneur du domaine Van Peers,\r\n<E042><CNTR><E003 12>confesse par la présente les faits suivants : »");
                R(ref s, "‘I am the killer who has come to be known in society\r\n<E042><CNTR>as “The Professor”, <E003 10>guilty of four counts of murder.’", "« Je suis le meurtrier que l'opinion publique a baptisé\r\n<E042><CNTR>“le Professeur”, <E003 10>coupable de quatre homicides. »");
                R(ref s, "‘I will not here discourse the corruption rife among the\r\n<E042><CNTR>aristocracy, <E003 8>which is to me, <E003 8>as one of them, <E003 10>so apparent.’", "« Je ne m'étendrai point céans sur la corruption qui gangrène\r\n<E042><CNTR>l'aristocratie, <E003 8>qui ne m'est, <E003 8>en tant que pair, <E003 10>que trop familière. »");
                R(ref s, "‘However, <E003 10>six months ago, <E003 12>I took the life of a member\r\n<E042><CNTR>of the House of Lords at the heart of the depravity.’", "« Toutefois, <E003 10>il y a six mois, <E003 12>j'ai ôté la vie d'un membre\r\n<E042><CNTR>de la Chambre des Lords qui se trouvait au cœur de cette perversion. »");
                R(ref s, "‘A demon<E003 12> who habitually sacrificed the common man to\r\n<E042><CNTR>further his own interests,<E003 8> abusing his position of power.’", "« Un démon<E003 12> qui sacrifiait impunément le peuple pour assouvir\r\n<E042><CNTR>ses desseins cupides,<E003 8> abusant de sa position de pouvoir. »");
                R(ref s, "‘The law is impotent against such vile avarice.<E003 12>\r\n<E042><CNTR>Only a fellow demon can rid society of this menace.’", "« Les lois sont impuissantes face à une telle félonie.<E003 12>\r\n<E042><CNTR>Seul un démon semblable pouvait purger la société d'un tel fléau. »");
                R(ref s, "‘That demon was my quarry,<E003 8>\r\n<E042><CNTR>upon whom I willingly set my great hound.’", "« Ce démon fut ma proie,<E003 8>\r\n<E042><CNTR>sur laquelle j'ai sciemment lâché mon molosse. »");
                R(ref s, "‘But though I am a hunter of some experience, <E003 12>\r\n<E042><CNTR>I am a poor felon, it seems.’", "« Mais si je suis un chasseur chevronné, <E003 12>\r\n<E042><CNTR>je ne suis qu'un bien piètre criminel. »");
                R(ref s, "‘My guilt was at once recognised by another, <E003 12>\r\n<E042><CNTR>and I became subject to his extortion.’", "« Mon crime fut aussitôt percé à jour par un tiers, <E003 12>\r\n<E042><CNTR>et je devins l'objet de son odieux chantage. »");
                R(ref s, "‘He held over me the threat of exposing my\r\n<E042><CNTR>wicked crime to my beloved wife and brother.’", "« Il brandit au-dessus de ma tête la menace de révéler\r\n<E042><CNTR>mon forfait abominable à mon épouse adorée et à mon frère. »");
                R(ref s, "‘Under that threat, <E003 10>I have done this man's bidding\r\n<E042><CNTR>for months now, <E003 12>killing those he demanded I kill.’", "« Sous le joug de ce chantage, <E003 10>j'ai exécuté ses ordres\r\n<E042><CNTR>des mois durant, <E003 12>abattant quiconque il m'ordonnait d'exécuter. »");
                R(ref s, "‘As I watched my former mentor perish before\r\nmy eyes at the jaws of the hound I commanded...’", "« En voyant mon ancien mentor périr sous mes yeux\r\nentre les crocs du molosse que je commandais... »");
                R(ref s, "‘...I realised that I had lost the last shred of decency\r\nwithin me...<E003 10><E074 1 7><E003 4>and sunk to the level of a wild beast.’", "« ...j'ai compris que j'avais perdu l'ultime parcelle d'humanité\r\nen moi...<E003 10><E074 1 7><E003 4>pour déchoir au rang d'une bête féroce. »");
                R(ref s, "‘There is no path back to the light.<E049><E003 15> Be it I<E003 10> or my dear\r\n<E042><CNTR>friend Asogi who dies this night...<E003 15>I am eternally damned.’", "« Il n'est plus de rédemption possible.<E049><E003 15> Que ce soit moi<E003 10> ou mon cher\r\n<E042><CNTR>ami Asogi qui succombe cette nuit...<E003 15>je suis damné pour l'éternité. »");
                R(ref s, "‘To my extortioner, <E003 10>Mael Stronghart...<E003 20><E025 3>may you feel the\r\n<E042><CNTR>jaws of <E074 0 0><E338>the <E074 1 5>beast at your throat<E003 10> every time you swallow.’", "« À mon maître-chanteur, <E003 10>Mael Stronghart...<E003 20><E025 3>puissiez-vous sentir les\r\n<E042><CNTR>crocs de <E074 0 0><E338>la <E074 1 5>bête à votre gorge<E003 10> à chacune de vos respirations. »");
                return s;
            };

