            entryTranslators[@"BB\script\output\_sce04_c403_0060_eng#3"] = (s) => {
                R(ref s, "So now we know!<E049><E003 10> <E025 3>Yes, <E049><E003 10>Klint van Zieks was <E006>a murderer<E005>...", "Nous savons désormais tout !<E049><E003 10> <E025 3>Oui, <E049><E003 10>Klint Van Peers était <E006>un meurtrier<E005>...");
                R(ref s, "...but somebody was directing him and naming his\r\nvictims.", "...mais quelqu'un le guidait dans l'ombre et désignait ses\r\nvictimes.");
                R(ref s, "His <E006>extortioner<E005>, <E049><E003 8>Lord Mael Stronghart...<E049><E003 14><E164 1 9 1 2 8 0 1 1><E139 1><E025 1>it was you!", "Son <E006>maître-chanteur<E005>, <E049><E003 8>Lord Mael Stronghart...<E049><E003 14><E164 1 9 1 2 8 0 1 1><E139 1><E025 1>ce n'était autre que vous !");
                R(ref s, "Lord Stronghart, <E049><E003 8><E025 3>a moment ago...", "Lord Stronghart, <E049><E003 8><E025 3>il y a un instant...");
                R(ref s, "...you claimed that what the court has just heard could\r\ndestroy justice in this country.", "...vous prétendiez que ce que la cour vient d'entendre anéantirait\r\nla justice de notre pays.");
                R(ref s, "But you weren't trying to protect justice at all.<E049><E003 12>\r\nAll you were trying to do...", "Mais ce n'est point la justice que vous cherchiez à préserver.<E049><E003 12>\r\nTout ce que vous tentiez de faire...");
                R(ref s, "...was conceal the secret of <E006>your true nature<E005> <E049><E003 10><E025 2>and the\r\ncountless lives you've sacrificed up till now!", "...c'était enfouir le secret de <E006>votre véritable nature<E005> <E049><E003 10><E025 2>et les\r\ninnombrables vies que vous avez sacrifiées jusqu'à ce jour !");
                R(ref s, "...It just didn't make sense to me.", "...Rien de tout cela n'avait de sens pour moi.");
                R(ref s, "That the third victim, <E049><E003 10><E025 2>the former Lord Chief Justice, <E049><E003 8><E025 3>was\r\nmy brother's benefactor, <E049><E003 8>and a man of lofty principles.", "La troisième victime, <E049><E003 10><E025 2>l'ancien Lord juge en chef, <E049><E003 8><E025 3>était\r\nle bienfaiteur de mon frère, <E049><E003 8>un homme d'une droiture exemplaire.");
                R(ref s, "As I said...<E003 15><E025 1><E332>Klint had no possible reason to kill the man!", "Comme je l'ai déjà dit...<E003 15><E025 1><E332>Klint n'avait aucune raison d'attenter à sa vie !");
                R(ref s, "But you did, <E049><E003 8>didn't you, <E049><E003 8><E341>Lord Stronghart?", "Mais vous en aviez une, <E049><E003 8>n'est-ce pas, <E049><E003 8><E341>Lord Stronghart ?");
                R(ref s, "To eliminate the man <E049><E003 12><E025 1><E335>who stood between you and the\r\noffice you'd set your sights on!", "Éliminer l'homme <E049><E003 12><E025 1><E335>qui vous barrait l'accès à la charge\r\nsupérieure que vous convoitiez !");
                R(ref s, "So you used your own hunting dog –<E049><E003 6> Lord Klint van\r\nZieks –<E049><E003 8> to take him down!", "Vous avez donc usé de votre propre chien de chasse –<E049><E003 6> Lord Klint Van\r\nPeers –<E049><E003 8> pour l'abattre !");
                R(ref s, "It had to be done.", "Il le fallait.");
                R(ref s, "London's unsavoury shadows are deep, <E049><E003 8>and the arm of\r\nthe law fails to reach their depths.", "Les ténèbres de Londres sont insondables, <E049><E003 8>et le bras de\r\nla loi s'avère incapable d'en atteindre les abysses.");
                R(ref s, "Crime must be cut off at the roots!<E049><E003 15> <E025 2>But the Lord Chief\r\nJustice at the time couldn't see that!<E049><E003 10> <E025 2>He was weak!", "Le crime doit être éradiqué à la racine !<E049><E003 15> <E025 2>Mais le Lord juge en\r\nchef de l'époque refusait de l'admettre !<E049><E003 10> <E025 2>Il était bien trop faible !");
