                R(ref s, "Jigoku had fierce ambition.<E049><E003 10>\r\n<E025 3>...It made him easy to manipulate.", "Jigoku nourrissait une ambition dévorante.<E049><E003 10>\r\n<E025 3>...Ce qui le rendait fort aisé à manœuvrer.");
                R(ref s, "Ten years ago, <E049><E003 10><E025 2>after he'd stood trial for the destruction of\r\nthe witness stand, <E049><E003 8>I had words with him.", "Il y a dix ans, <E049><E003 10><E025 2>après son procès pour avoir fracassé\r\nla barre des témoins, <E049><E003 8>je me suis entretenu avec lui.");
                R(ref s, "When I told him the position of Minister of Foreign Affairs\r\ncould be his, <E049><E003 8><E333><E025 2>he couldn't agree fast enough!", "Quand je lui ai fait miroiter le poste de ministre des Affaires étrangères,\r\n<E049><E003 8><E333><E025 2>il a sauté sur l'occasion sans hésiter !");
                R(ref s, "Seishiro...<E049><E003 12><E145 46 74><E118 46 1.6><E003 8><E149 46 0 0>\r\n<E025 3><E338><E342>You fool...", "Seishiro...<E049><E003 12><E145 46 74><E118 46 1.6><E003 8><E149 46 0 0>\r\n<E025 3><E338><E342>Pauvre fou...");
