            // [122] BB\script\output\_sce04_c403_0070_eng#2
            entryTranslators[@"BB\script\output\_sce04_c403_0070_eng#2"] = (s) => {
                R(ref s, "There was an unexpected visitor to the cemetery with\r\nhis own ideas about digging up graves.", "Un intrus inattendu s'était introduit dans le cimetière, venu\r\nlui aussi pour profaner des sépultures.");
                R(ref s, "A man who witnessed <E003 8><E070 2 1 1><E071><E086 2 36><E070 0 3 1><E025 3>what <E006>nobody was supposed to see<E005>.", "Un homme qui fut témoin <E003 8><E070 2 1 1><E071><E086 2 36><E070 0 3 1><E025 3>de ce que <E006>nul ne devait jamais voir<E005>.");
                R(ref s, "Enoch Drebber...", "Enoch Drebber...");
                R(ref s, "Of course, <E049><E003 8><E025 2>I knew graverobbers frequented London's\r\ncemeteries.", "Certes, <E049><E003 8><E025 2>je savais que les pilleurs de tombes écumaient\r\nles nécropoles londoniennes.");
                R(ref s, "But that grave on that particular night...", "Mais cette tombe-là, en cette nuit précise...");
                R(ref s, "Blast!<E003 18>\r\n<E042><CNTR><E025 2>If people find out the convict wasn't really executed...", "Malediction !<E003 18>\r\n<E042><CNTR><E025 2>Si le monde apprend que le condamné n'a pas été exécuté...");
                R(ref s, "...the scandal will rock the very\r\n<E042><CNTR>foundations of the empire!", "...le scandale ébranlera l'empire tout entier\r\n<E042><CNTR>jusque dans ses fondations !");
                R(ref s, "Then, <E003 8><E341>then what do we do?", "Mais... <E003 8><E341>que fait-on alors ?");
                R(ref s, "Shoot him, <E003 6>Mr Jigoku!<E003 14>\r\n<E042><CNTR>Shoot Asogi at once!", "Tirez, <E003 6>Monsieur Jigoku !<E003 14>\r\n<E042><CNTR>Abattez Asogi sur-le-champ !");
                R(ref s, "He can't live now this has happened!<E003 12>\r\n<E042><CNTR>He has to go!", "Il ne peut plus rester en vie après cela !<E003 12>\r\n<E042><CNTR>Il doit disparaître !");
                R(ref s, "What are you talking about?<E003 15>\r\n<E042><CNTR><E338><E342>You had an agreement!", "Mais de quoi parlez-vous ?<E003 15>\r\n<E042><CNTR><E338><E342>Vous aviez un accord !");
