            // [123] BB\script\output\_sce04_c403_0070_eng#3
            entryTranslators[@"BB\script\output\_sce04_c403_0070_eng#3"] = (s) => {
                R(ref s, "It was Jigoku, <E049><E003 10>your Japanese acquaintance, <E049><E003 16>who killed\r\nAsogi in the end, <E049><E003 6>you see.", "C'est Jigoku, <E049><E003 10>votre estimé compatriote, <E049><E003 16>qui a tué\r\nAsogi au bout du compte, <E049><E003 6>voyez-vous.");
                R(ref s, "He claimed to be the man's friend, <E049><E003 10><E025 2>but when push came\r\nto shove, <E049><E003 10><E025 3>he pulled the trigger.", "Il se prétendait son ami, <E049><E003 10><E025 2>mais acculé au pied\r\ndu mur, <E049><E003 10><E025 3>il n'a pas hésité à tirer.");
                R(ref s, "Just before Mr Jigoku left the courtroom earlier...", "Juste avant que M. Jigoku ne quitte ce prétoire tout à l'heure...");
                R(ref s, "...he said that the assassin exchange proposal <E049><E003 10><E330><E025 3>was <E006>a\r\ndemand<E005> from his British counterpart, <E049><E003 8><E025 3>not a request.", "...il a précisé que ce troc d'assassins <E049><E003 10><E330><E025 3>était <E006>une\r\nexigence<E005> de son homologue britannique, <E049><E003 8><E025 3>et non une simple requête.");
                R(ref s, "So you coerced him, too?<E049><E003 12><E164 112 7 1 2 1 0 2 1><E118 112 1.2><E139 112>\r\n<E025 1>Using what happened in the graveyard!", "Vous l'avez donc fait chanter lui aussi ?<E049><E003 12><E164 112 7 1 2 1 0 2 1><E118 112 1.2><E139 112>\r\n<E025 1>En brandissant les événements du cimetière !");
                R(ref s, "By that time, <E049><E003 8>Jigoku was the Minister of Foreign Affairs\r\nnegotiating international treaties with Britain.", "À cette date, <E049><E003 8>Jigoku était ministre des Affaires étrangères,\r\nen pourparlers pour des traités majeurs avec la Grande-Bretagne.");
                R(ref s, "You can imagine what would have happened if it came\r\nto light he'd murdered a compatriot ten years earlier.", "Imaginez le désastre s'il s'était su qu'il avait abattu\r\nun compatriote dix ans plus tôt.");
                R(ref s, "He would have lost everything.<E049><E003 18><E145 61 4><E118 61 0.5><E003 10>\r\n<E025 3>...I merely reminded him of that.", "Il aurait tout perdu d'un seul coup.<E049><E003 18><E145 61 4><E118 61 0.5><E003 10>\r\n<E025 3>...Je me suis contenté de le lui rappeler.");
                R(ref s, "How do you <E049><E003 8><E338><E341><E025 2>sleep at night...?", "Comment faites-vous pour <E049><E003 8><E338><E341><E025 2>dormir la nuit... ?");
                R(ref s, "These past ten years, <E049><E003 8><E025 2>I've fought tirelessly with the\r\ndarker recesses of London's criminal underworld.", "Ces dix dernières années, <E049><E003 8><E025 2>j'ai lutté sans répit contre\r\nla lie du monde criminel londonien.");
                R(ref s, "And I've used whatever means necessary <E049><E003 12><E145 61 5><E025 1><E332>to ensure that\r\njustice prevails and law and order reign supreme!", "Et j'ai usé de tous les moyens nécessaires <E049><E003 12><E145 61 5><E025 1><E332>pour que triomphe\r\nla justice et que règne l'ordre absolu !");
                R(ref s, "That couldn't be further from the truth.", "C'est absolument faux.");
                R(ref s, "The fact is...<E049><E003 12><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>you haven't fought crime at all!", "La vérité...<E049><E003 12><E164 1 8 1 2 5 0 2 1><E139 1><E025 1>c'est que vous n'avez pas combattu le crime !");
                R(ref s, "How dare you?!", "Comment osez-vous ?!");
                R(ref s, "I saved Klint van Zieks <E049><E003 2><E145 61 14><E003 15><E025 1><E046>from dishonour in his death!", "J'ai sauvé Klint Van Peers <E049><E003 2><E145 61 14><E003 15><E025 1><E046>du déshonneur posthume !");
                return s;
            };

            // [124] BB\script\output\_sce04_c403_0070_eng#4
            entryTranslators[@"BB\script\output\_sce04_c403_0070_eng#4"] = (s) => {
                R(ref s, "Whilst behind the scenes, <E049><E003 8>you systematically buried\r\nanyone who stood in your way.", "Alors que dans l'ombre, <E049><E003 8>vous éliminiez méthodiquement\r\nquiconque osait se dresser en travers de votre chemin.");
                R(ref s, "And then <E049><E003 3><E164 112 10 1 2 8 0 2 1><E139 112><E025 1>you made my father take the blame!", "Et pour couronner le tout, <E049><E003 3><E164 112 10 1 2 8 0 2 1><E139 112><E025 1>vous avez fait porter tout le chapeau à mon père !");
                R(ref s, "It was unavoidable!<E049><E003 12> <E342><E025 1>It was the only way to protect our\r\njustice system and public order!", "C'était inéluctable !<E049><E003 12> <E342><E025 1>C'était l'unique moyen de préserver\r\nnotre système judiciaire et l'ordre public !");
                R(ref s, "Let's not forget <E145 112 0><E118 112 0.95>the others you had killed as well.", "Sans compter tous les autres <E145 112 0><E118 112 0.95>que vous avez également fait assassiner.");
                R(ref s, "Setting the defendant up as the Reaper to cover up the\r\nmurders of countless more!", "Désignant l'accusé comme le Faucheur pour masquer\r\nles meurtres de tant d'autres !");
                R(ref s, "That's<E341>...<E049><E003 10><E145 61 28><E139 61><E025 1><E339><E085 3 26>ENOOOUGH!", "C'en est...<E049><E003 10><E145 61 28><E139 61><E025 1><E339><E085 3 26>ASSEEEZ !");
                R(ref s, "Do you have any idea of the conniving that led to the\r\nacquittals <E049><E003 10><E025 1><E045>of those WRETCHED criminals?!", "Avez-vous la moindre idée des manigances qui avaient permis l'acquittement\r\n<E049><E003 10><E025 1><E045>de ces MISÉRABLES scélérats ?!");
                R(ref s, "We have to fight fire with fire!<E049><E003 12>\r\n<E338><E342>Our courts can't function without a Reaper!", "Il faut combattre le mal par le mal !<E049><E003 12>\r\n<E338><E342>Nos tribunaux ne peuvent fonctionner sans un Faucheur !");
                R(ref s, "Can't you see all I've done for this country?!<E049><E003 12>\r\nThis has been my struggle!", "Ne voyez-vous point tout ce que j'ai accompli pour cette nation ?!<E049><E003 12>\r\nTel a été mon combat !");
                R(ref s, "You've done nothing!", "Vous n'avez rien fait du tout !");
                R(ref s, "It's Lord van Zieks here who worked tirelessly and justly\r\nin court,<E049><E003 10> <E025 1><E346>whilst enduring the disgrace of the Reaper name!", "C'est Lord Van Peers qui s'est dévoué corps et âme avec droiture\r\nau prétoire,<E049><E003 10> <E025 1><E346>en endurant l'opprobre infâme du titre de Faucheur !");
                R(ref s, "And Inspector Gregson!<E049><E003 12> Fraught with anguish for having\r\nsullied his hands through a desire to do the right thing!", "Et l'inspecteur Gregson !<E049><E003 12> Rongé par le remords d'avoir\r\nsouillé ses mains pour faire ce qui lui semblait juste !");
                R(ref s, "Not to mention Genshin Asogi, <E049><E003 10><E025 1>who risked his life going\r\nin pursuit of the truth you tried to hide!", "Sans oublier Genshin Asogi, <E049><E003 10><E025 1>qui a bravé la mort pour\r\ntraquer la vérité que vous cherchiez à étouffer !");
                R(ref s, "No, <E049><E003 8><E025 2>the darker recesses of London's underworld...<E049><E003 10><E164 1 8 1 2 8 0 2 1><E139 1><E025 1>were\r\nlargely filled by you!", "Non, <E049><E003 8><E025 2>les recoins les plus fangeux de la pègre londonienne...<E049><E003 10><E164 1 8 1 2 8 0 2 1><E139 1><E025 1>étaient\r\nlargement occupés par vous !");
                R(ref s, "You little<E341>...<E003 15>\r\n<E025 3><E341>When will you get it through <E342>your thick skulls...?", "Espèces de petits...<E003 15>\r\n<E025 3><E341>Quand allez-vous enfin vous mettre cela <E342>dans le crâne... ?");
                R(ref s, "That it was all for Queen and Country?<E049><E003 14>\r\n<E025 2><E338><E341>I'm tiring of that excuse.", "Que tout cela était pour la Reine et la patrie ?<E049><E003 14>\r\n<E025 2><E338><E341>Cette antienne commence à me lasser.");
                R(ref s, "You've consistently twisted the truth for bargaining power\r\nto make others do your bidding.<E049><E003 10> <E025 3>Nothing more.", "Vous avez sans cesse travesti la vérité pour vous forger un moyen de pression\r\net asservir autrui à vos volontés.<E049><E003 10> <E025 3>Rien de plus.");
                R(ref s, "People who willingly twist the truth and coerce others<E049><E003 12>\r\n<E025 1><E338><E341>have no right to call themselves part of the judiciary!", "Quiconque déforme délibérément la vérité et fait chanter ses semblables<E049><E003 12>\r\n<E025 1><E338><E341>n'a nullement le droit de se prétendre membre de la justice !");
                R(ref s, "I strongly suggest, <E049><E003 10><E549 7 19 3 1><E003 3><E346><E342><E339><E025 1>you don't EVER talk of justice again!", "Je vous conseille solennellement, <E049><E003 10><E549 7 19 3 1><E003 3><E346><E342><E339><E025 1>de ne JAMAIS plus prononcer le mot justice !");
                R(ref s, "Grrr...<E003 8> <E338><E342>Garrrrrrrrr...", "Grrr...<E003 8> <E338><E342>Garrrrrrrrr...");
                R(ref s, "GAAAAAAAAAAAAAAAAAAAAA<E606>AAAAAAAAAAAA\r\nAAAAAAAAA<E338>AAAAAAAAAAA<E342>AAAAAAAAAAAAGH!", "GAAAAAAAAAAAAAAAAAAAAA<E606>AAAAAAAAAAAA\r\nAAAAAAAAA<E338>AAAAAAAAAAA<E342>AAAAAAAAAAAAGH !");
                return s;
            };

            // [125] BB\script\output\_sce04_c404_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c404_0000_eng#2"] = (s) => {
                R(ref s, "Well, <E049><E003 6>well, <E049><E003 6>well<E025 0>...<E049><E003 25><E264 61 1.2>\r\n<E342><E025 2>Dear me, <E049><E003 8><E025 1><E338><E342>my good fellows!<E049><E003 16> Dear me!", "Bien, <E049><E003 6>bien, <E049><E003 6>bien<E025 0>...<E049><E003 25><E264 61 1.2>\r\n<E342><E025 2>Grands dieux, <E049><E003 8><E025 1><E338><E342>mes chers amis !<E049><E003 16> Grands dieux !");
                R(ref s, "A well-deserved round of applause, I think, <E049><E003 14><E264 61 1.5><E607><E025 1><E339>for a quite\r\nmarvellous performance!", "Des applaudissements bien mérités, ma foi, <E049><E003 14><E264 61 1.5><E607><E025 1><E339>pour une déclamation\r\ntout à fait spectaculaire !");
                R(ref s, "W-<E049><E003 6><E164 1 71 1 2 9 0 2 1><E118 1 1.2><E139 1><E025 1>What are you talking about?", "M-<E049><E003 6><E164 1 71 1 2 9 0 2 1><E118 1 1.2><E139 1><E025 1>De quoi parlez-vous donc ?");
                R(ref s, "Those delightfully grave expressions!<E049><E003 16><E264 61 1.8>\r\n<E607>That beautifully pronounced Queen's English!", "Ces mines si délicieusement solennelles !<E049><E003 16><E264 61 1.8>\r\n<E607>Cet anglais de la Reine si magistralement déclamé !");
                R(ref s, "Really, <E049><E003 14><E264 61 2.2><E607><E025 1><E339>our friends from the Far East are quite the picture\r\nof industriousness!", "Vraiment, <E049><E003 14><E264 61 2.2><E607><E025 1><E339>nos amis d'Extrême-Orient sont un modèle absolu\r\nde zèle et de ferveur !");
                R(ref s, "You fraud...<E049><E003 10> <E164 112 7 1 2 9 0 3 1><E139 112><E025 1>Keep your mockery!", "Imposteur...<E049><E003 10> <E164 112 7 1 2 9 0 3 1><E139 112><E025 1>Gardez vos sarcasmes !");
                R(ref s, "Please, <E049><E003 10><E025 2>don't misunderstand!<E049><E003 15><E145 61 27><E149 61 0 7><E003 25>\r\n<E333><E025 3>It really is exactly as you've both said.", "Je vous en prie, <E049><E003 10><E025 2>ne vous méprenez pas !<E049><E003 15><E145 61 27><E149 61 0 7><E003 25>\r\n<E333><E025 3>Tout est rigoureusement conforme à vos dires.");
                R(ref s, "What are you trying to say?", "Qu'insinuez-vous ?");
                R(ref s, "I have occupied the darker recesses of London's\r\nunderworld and –<E049><E003 12> <E025 3>how did you put it?<E049><E003 16> <E239><E025 3>‘Done nothing’?", "J'ai hanté les recoins les plus obscurs de la pègre\r\nlondonienne et –<E049><E003 12> <E025 3>comment disiez-vous ?<E049><E003 16> <E239><E025 3>« Je n'ai rien fait » ?");
                R(ref s, "I confess it's a little embarrassing to have it pointed out\r\nquite so starkly, <E049><E003 6>but yes...", "J'avoue qu'il est un peu embarrassant de se l'entendre asséner\r\nsi crûment, <E049><E003 6>mais en vérité...");
                R(ref s, "...I really have ‘<E006>done nothing<E005>’.<E049><E003 14>\r\n<E025 3>Which means...", "...je n'ai concrètement « <E006>rien fait<E005> ».<E049><E003 14>\r\n<E025 3>Ce qui implique...");
                R(ref s, "...I can be indicted for nothing.<E049><E003 14>\r\n<E025 3>...No?", "...que l'on ne peut m'inculper de rien.<E049><E003 14>\r\n<E025 3>...N'est-ce pas ?");
                R(ref s, "WHAT?!", "QUOI ?!");
                R(ref s, "It's true!<E049><E003 12><E145 61 10><E118 61 1.25><E003 10> <E025 3>Person<E172 61 0 0 0 0 4>ally, <E049><E003 10><E025 1><E338><E341>I have committed no crime!", "C'est pourtant vrai !<E049><E003 12><E145 61 10><E118 61 1.25><E003 10> <E025 3>Person<E172 61 0 0 0 0 4>nellement, <E049><E003 10><E025 1><E338><E341>je n'ai commis aucun crime !");
                R(ref s, "I've merely been surrounded by fools <E049><E003 5><E164 61 11 1 2 5 0 2 1><E139 61><E025 1>who've acted very\r\nrashly indeed!", "J'ai simplement été entouré d'imbéciles <E049><E003 5><E164 61 11 1 2 5 0 2 1><E139 61><E025 1>qui ont agi de manière\r\nfort inconsidérée !");
                R(ref s, "You, <E049><E003 6><E025 1><E164 1 71 1 2 9 0 2 1><E118 1 1.2><E139 1>you can't get away with that!<E049><E003 12>\r\n<E025 2><E338><E341>You've consistently preyed on people's weaknesses...", "Vous... <E049><E003 6><E025 1><E164 1 71 1 2 9 0 2 1><E118 1 1.2><E139 1>vous n'allez pas vous en tirer ainsi !<E049><E003 12>\r\n<E025 2><E338><E341>Vous avez systématiquement exploité la faiblesse d'autrui...");
                R(ref s, "And what?<E049><E003 12> <E239><E025 3>Threatened them?<E049><E003 16>\r\n<E025 3>Are you sure it wasn't just bargaining?", "Et après ?<E049><E003 12> <E239><E025 3>Des menaces ?<E049><E003 16>\r\n<E025 3>N'était-ce pas plutôt de simples négociations ?");
                R(ref s, "I would like to address all the good lords, <E049><E003 8>ladies <E049><E003 6>and\r\ngentlemen of the judiciary here present.", "J'aimerais m'adresser à tous les éminents pairs, dames et\r\nmessieurs de la magistrature ici présents.");
                R(ref s, "You all know of these darker recesses in our great capital.<E049><E003 12>\r\n<E025 3>And deep down, <E049><E003 8><E025 3>I believe you also know...", "Vous connaissez tous l'existence de ces bas-fonds au sein de notre capitale.<E049><E003 12>\r\n<E025 3>Et au fond de vous, <E049><E003 8><E025 3>je sais que vous comprenez...");
                R(ref s, "...that to fight those who dwell there <E049><E003 10><E239>requires at least\r\nsome of us to occupy the darkness ourselves.", "...que pour vaincre les monstres qui y rôdent, <E049><E003 10><E239>il nous faut\r\nparfois descendre nous-mêmes dans ces ténèbres.");
                R(ref s, "So let me appeal to your good sense now.<E049><E003 10>\r\n<E025 3>Consider the situation with me...", "J'en appelle donc à votre sagesse et à votre raison.<E049><E003 10>\r\n<E025 3>Considérons la situation posément...");
                R(ref s, "If this catalogue of horrifying revelations...", "Si cette litanie d'effroyables révélations...");
                R(ref s, "...were to become common knowledge among the six\r\nmillion inhabitants of London, <E049><E003 10><E025 3>what might happen?", "...venait à être étalée aux yeux des six\r\nmillions d'habitants de Londres, <E049><E003 10><E025 3>qu'adviendrait-il donc ?");
                R(ref s, "To learn that the infamous murderer of royals and nobles\r\nwas a respected member of the aristocracy himself...", "Apprendre que le sinistre assassin de pairs et de nobles\r\nétait lui-même un éminent membre de l'aristocratie...");
                R(ref s, "That evidence was fabricated in the scapegoat's trial amid\r\nsecret negotiations with prosecutors to effect a jailbreak...", "Que les preuves ont été falsifiées lors du procès d'un bouc émissaire,\r\nsur fond d'évasion secrète négociée avec le parquet...");
                R(ref s, "That the Reaper of the Bailey was an organised group of\r\nassassins managed by a Scotland Yard inspector...", "Que le Faucheur de la Cour était un réseau d'assassins\r\nsupervisé par un inspecteur de Scotland Yard...");
                R(ref s, "And finally...", "Et enfin...");
                R(ref s, "...that it was all masterminded by the Lord Chief Justice\r\nhimself!", "...que tout cela était orchestré par le Lord juge en chef\r\nen personne !");
                R(ref s, "If the general public of Britain knew the truth...", "Si le peuple de Grande-Bretagne apprenait cette vérité...");
                R(ref s, "...all faith in the police and the Prosecutor's Office <E049><E003 5><E145 112 0><E118 112 0.7><E149 112 0 4><E003 10><E025 3><E333>would\r\nbe completely lost...<E003 12>without doubt.", "...toute foi dans la police et dans l'institution judiciaire <E049><E003 5><E145 112 0><E118 112 0.7><E149 112 0 4><E003 10><E025 3><E333>s'effondrerait\r\ninstantanément... <E003 12>à n'en point douter.");
                R(ref s, "Public order in the capital would completely break down.<E049><E003 14>\r\n<E025 2><E338><E341>We'd be cast back to the lawless days of the last century.", "L'ordre public dans la capitale volerait en éclats.<E049><E003 14>\r\n<E025 2><E338><E341>Nous replongerions dans l'anarchie barbare du siècle passé.");
                R(ref s, "Precisely.<E049><E003 10> <E025 2>As it was a hundred years ago, <E049><E003 6>when one in ten\r\nof the population were criminals.", "Parfaitement.<E049><E003 10> <E025 2>Comme il y a cent ans, <E049><E003 6>quand un habitant sur dix\r\nétait un malfrat.");
                R(ref s, "Think what we've accomplished since then:<E049><E003 12> <E025 3>a public\r\npolicing force, <E049><E003 8>a comprehensive set of laws...", "Songez à tout ce que nous avons bâti depuis :<E049><E003 12> <E025 3>une force\r\npolicière, <E049><E003 8>un corpus de lois inattaquables...");
                R(ref s, "And if we want to continue to protect this new era of law\r\nand order...", "Et si nous souhaitons préserver cette nouvelle ère de paix\r\net d'ordre...");
                R(ref s, "...I say again:<E049><E003 14> <E164 61 33 1 2 5 0 2 0><E139 61><E025 1><E339>we must at times <E049><E003 14><E346>occupy the darkness\r\nourselves!", "...je le répète haut et fort :<E049><E003 14> <E164 61 33 1 2 5 0 2 0><E139 61><E025 1><E339>nous devons parfois <E049><E003 14><E346>habiter les ténèbres\r\nnous-mêmes !");
                R(ref s, "We have successfully identified and apprehended the\r\nman responsible for taking Inspector Gregson's life.", "Nous avons identifié et écroué l'individu coupable d'avoir\r\nôté la vie à l'inspecteur Gregson.");
                R(ref s, "That is all that was expected of this trial.<E049><E003 15>\r\n<E025 2>All these other matters that have been discussed...", "C'était là l'unique objet attendu de cette cour.<E049><E003 15>\r\n<E025 2>Toutes les autres considérations évoquées céans...");
                R(ref s, "...will be eliminated from the minutes of these\r\nproceedings...<E049><E003 14><E025 1>in the interests of preserving law and order!", "...seront purement et simplement effacées des registres...<E049><E003 14><E025 1>dans l'intérêt supérieur de la loi et de l'ordre !");
                R(ref s, "And to protect Her Majesty the Queen, <E049><E003 6>of course.", "Et pour préserver l'honneur de Sa Majesté la Reine, <E049><E003 6>bien entendu.");
                R(ref s, "Well, <E049><E003 6><E164 61 12 1 2 8 0 2 0><E118 61 1.1><E003 9><E172 61 0 0 18 0 6><E139 61><E094 1 21 4><E025 1><E339>my lords, ladies and gentlemen?<E049><E093 1 22 4><E003 16>\r\n<E342><E025 2><E338>What say you?", "Alors, <E049><E003 6><E164 61 12 1 2 8 0 2 0><E118 61 1.1><E003 9><E172 61 0 0 18 0 6><E139 61><E094 1 21 4><E025 1><E339>mesdames et messieurs de la cour ?<E049><E093 1 22 4><E003 16>\r\n<E342><E025 2><E338>Qu'en dites-vous ?");
                R(ref s, "He has a point...", "Il n'a pas tort...");
                R(ref s, "The things Lord Stronghart has\r\n<E042><CNTR>done are quite unforgivable...", "Ce que Lord Stronghart a commis\r\n<E042><CNTR>est certes impardonnable...");
                R(ref s, "But on the other hand...", "Mais d'un autre côté...");
                R(ref s, "Isn't it our duty to maintain\r\n<E042><CNTR>law and order in the capital?", "N'est-ce pas notre devoir sacré de maintenir\r\n<E042><CNTR>l'ordre et la paix dans la capitale ?");
                R(ref s, "You can't deny that the threat of the Reaper over\r\n<E042><CNTR>the years has done wonders for the crime rate...", "On ne peut nier que la terreur du Faucheur\r\n<E042><CNTR>a fait chuter la criminalité de façon spectaculaire...");
                R(ref s, "And by fair means or foul, <E003 16>\r\n<E042><CNTR><E607><E025 1>that's all thanks to Lord Stronghart!", "Et que ce soit par le bien ou par le mal, <E003 16>\r\n<E042><CNTR><E607><E025 1>c'est grâce à Lord Stronghart !");
                R(ref s, "Strong<E003 16>hart!<E003 18> Strong<E003 16>hart!<E003 18>\r\n<E042><CNTR><E338><E341>Strong<E003 16>hart!<E003 18> Strong<E003 16>hart!<E003 18>", "Strong<E003 16>hart !<E003 18> Strong<E003 16>hart !<E003 18>\r\n<E042><CNTR><E338><E341>Strong<E003 16>hart !<E003 18> Strong<E003 16>hart !<E003 18>");
                R(ref s, "Are, <E049><E003 12>are you hearing this?", "En... <E049><E003 12>entendez-vous cela ?");
                R(ref s, "This is the will of the British judiciary?!", "Serait-ce là la volonté de la magistrature britannique ?!");
                return s;
            };

